import {taskView} from './task-world.mjs';
import {PARTS,SENSORS} from './task-data.mjs';
export function mountDrawing({stage,panel,day,flat,onChange,onComplete,onExit,checkSession}){
 const surface=document.createElement('div');surface.className='space-surface task-surface';stage.append(surface);document.body.classList.add('space-session');document.body.dataset.spacePhase='drawing';
 let canvas=document.createElement('canvas');canvas.setAttribute('aria-label','도면의 도킹 링과 여섯 부품');surface.append(canvas);let view=taskView(canvas,{flat});
 if(!view){canvas.replaceWith(canvas=document.createElement('canvas'));surface.append(canvas);view=taskView(canvas,{flat:true})}
 panel.innerHTML='<div class="space-heading">09:30 · 도면 책상 · 지상 시험</div><h2>접속 통로를 막는 곳 세 군데를 찾아요.</h2><p>도면의 링 안으로 길게 들어온 부품을 눌러요. 옆 모형에서도 같은 부품이 빨갛게 바뀌어요.</p><p id="drawingHint" role="status">도면과 모형을 함께 살펴요.</p><p id="drawingProgress"></p><details><summary>부품 이름</summary><ol>'+PARTS.map(p=>'<li>'+p.name+'</li>').join('')+'</ol></details><div class="space-actions"><button class="wd-btn" id="drawingDone">수정 요청을 제작팀에 전달</button><button id="returnHall">← 시험동으로</button></div>';
 const targets=PARTS.map((part,i)=>{const b=document.createElement('button');b.className='space-target drawing-target';b.dataset.part=i;b.textContent=i+1;b.setAttribute('aria-label',`${i+1}번 ${part.name} 점검`);b.onclick=()=>{if(!checkSession())return;const r=day.inspectDrawing(i);document.getElementById('drawingHint').textContent=r.note;onChange();refresh()};surface.append(b);return b});
 function refresh(){view.draw(day.drawingFound);targets.forEach((b,i)=>{const p=view.point(i);b.style.left=p.x+'px';b.style.top=p.y+'px';b.setAttribute('aria-pressed',String(day.drawingFound.has(i)))});document.getElementById('drawingProgress').textContent=`간섭 ${day.drawingFound.size}/3 확인 · 재확인 ${day.drawingDelay}분 · 현재 ${day.delay}분 밀림`;document.getElementById('drawingDone').disabled=day.drawingFound.size!==3}
 document.getElementById('drawingDone').onclick=()=>{if(checkSession()&&day.drawingFound.size===3)onComplete()};document.getElementById('returnHall').onclick=onExit;
 const observer=new ResizeObserver(()=>{view.resize();refresh()});observer.observe(surface);refresh();
 return{dispose(){observer.disconnect();view.dispose();surface.remove();document.body.classList.remove('space-session');delete document.body.dataset.spacePhase}};
}

export function mountSensors({stage,panel,day,flat,onChange=()=>{},onComplete,onExit,checkSession}){
 const surface=document.createElement('div');surface.className='space-surface task-surface';stage.append(surface);document.body.classList.add('space-session');document.body.dataset.spacePhase='sensor';
 let canvas=document.createElement('canvas');canvas.setAttribute('aria-label','도킹 링의 센서 연결부 세 곳');surface.append(canvas);let view=taskView(canvas,{flat,mode:'sensor'});if(!view){canvas.replaceWith(canvas=document.createElement('canvas'));surface.append(canvas);view=taskView(canvas,{flat:true,mode:'sensor'})}
 panel.innerHTML='<div class="space-heading">11:30 · 센서 작업대</div><h2>센서를 집어 링에 연결해요.</h2><p>센서의 일을 읽고 놓을 자리를 생각해요. 센서를 집으면 설명이 나와요.</p><p id="sensorHint" role="status">거리·중심·기록 신호가 모두 필요해요.</p><details><summary>센서의 일과 자리</summary><ul>'+SENSORS.map(s=>'<li>'+s.name+' · '+s.reason+'</li>').join('')+'</ul></details><p id="sensorProgress"></p><div class="space-actions"><button class="wd-btn" id="sensorDone">연결 확인 · 점심 먹으러 가기</button><button id="returnHall">← 시험동으로</button></div>';
 let drag=null;
 const ports=SENSORS.map((s,i)=>{const b=document.createElement('span');b.className='sensor-port';b.dataset.port=i;b.setAttribute('aria-label',['링 위쪽 빈 연결부','링 오른쪽 아래 빈 연결부','링 왼쪽 아래 빈 연결부'][i]);surface.append(b);return b});
 const chips=SENSORS.map((s,i)=>{const b=document.createElement('button');b.className='sensor-chip';b.dataset.sensor=i;b.textContent=s.name;b.onpointerdown=e=>{if(!checkSession()||day.sensors.has(i))return;e.preventDefault();b.setPointerCapture(e.pointerId);drag={id:e.pointerId,sensor:i,x:e.clientX,y:e.clientY};document.getElementById('sensorHint').textContent=s.name+' · '+s.reason;b.classList.add('dragging');const r=surface.getBoundingClientRect();view.moveChip(i,e.clientX-r.left,e.clientY-r.top)};b.onpointermove=e=>{if(drag?.id===e.pointerId){b.style.transform=`translate(-50%,0) translate(${e.clientX-drag.x}px,${e.clientY-drag.y}px)`;const r=surface.getBoundingClientRect();view.moveChip(i,e.clientX-r.left,e.clientY-r.top)}};const release=(e,cancel=false)=>{if(drag?.id!==e.pointerId)return;let port=-1;if(!cancel)port=ports.findIndex(p=>{const r=p.getBoundingClientRect();return Math.hypot(e.clientX-r.x-r.width/2,e.clientY-r.y-r.height/2)<Math.max(32,r.width*.65)});const r=cancel?{note:'집은 센서를 내려놓았어요.'}:day.attachSensor(i,port);document.getElementById('sensorHint').textContent=r.note;drag=null;b.style.transform='';b.classList.remove('dragging');onChange();refresh()};b.onpointerup=e=>release(e);b.onpointercancel=b.onlostpointercapture=e=>release(e,true);surface.append(b);return b});
 function refresh(){view.draw(day.sensors);ports.forEach((p,i)=>{const q=view.point(i*2,1.08);p.style.left=q.x+'px';p.style.top=q.y+'px';p.classList.toggle('filled',day.sensors.has(i))});chips.forEach((b,i)=>{b.disabled=day.sensors.has(i);b.textContent=(b.disabled?'✓ ':'')+SENSORS[i].name;const q=view.chipPoint(i);b.style.left=q.x+'px';b.style.top=(q.y+18)+'px'});document.getElementById('sensorProgress').textContent=`연결 ${day.sensors.size}/3 · 재확인 ${day.sensorWrong.size*2}분 · 현재 ${day.delay}분 밀림`;document.getElementById('sensorDone').disabled=day.sensors.size!==3}
 document.getElementById('sensorDone').onclick=()=>{if(checkSession()&&day.sensors.size===3)onComplete()};document.getElementById('returnHall').onclick=onExit;
 const observer=new ResizeObserver(()=>{view.resize();refresh()});observer.observe(surface);refresh();return{dispose(){observer.disconnect();view.dispose();surface.remove();document.body.classList.remove('space-session');delete document.body.dataset.spacePhase}};
}
